p='packages/std-program/src/query_engine.av'
t=open(p).read()
def sub(a,b):
    global t
    assert t.count(a)==1,(a[:60],t.count(a)); t=t.replace(a,b)
sub("let suspects? = self.suspects_of(f, changed) else","let suspects? = self.suspects_of(f, changed, all) else")
sub("""    /// Whether a change in `changed` reaches each answer of `f`; absent when its reads don't lie
    /// within it.
    fn suspects_of(f: Frontier, changed: List<int>) -> List<bool>? {
        if changed.is_empty() { return [false for _i in 0..f.length()] }
        let decided: Cell<List<int>> = Cell.new([0 for _i in 0..f.length()])
        f.readers_of(changed, (at) -> self.cut_at(f, at, decided))
    }""","""    /// Whether a change in `changed` reaches each answer of `f`, `reach` being what it reaches with
    /// no cut decided; absent when its reads don't lie within it. A cut a change reaches through an
    /// answer no cut decides is left to be asked (`plainly_reached`), never decided here.
    fn suspects_of(f: Frontier, changed: List<int>, reach: List<bool>) -> List<bool>? {
        if changed.is_empty() { return [false for _i in 0..f.length()] }
        let decided: Cell<List<int>> = Cell.new([0 for _i in 0..f.length()])
        let plain? = f.plainly_reached(changed, reach, (at) -> self.cuts_at(f, at)) else { return null }
        f.readers_of(changed, (at) -> self.cut_at(f, at, decided), plain)
    }

    /// Whether the answer at `at` is a cutting query's, of the code that asked it: one the frontier's
    /// opening may decide, as `cut_found` does, without working it out.
    fn cuts_at(f: Frontier, at: int) -> bool {
        let asked? = self.store.question_known_as(f.question_at(at)) else { return false }
        let definition? = self.definitions.get().get(asked.query_name) else { return false }
        definition.cuts && !definition.code_hash.is_empty() && definition.code_hash == asked.code_hash
    }""")
open(p,'w').write(t)
