export type FileWave = {
    is_known: fn(QueryEngine, SourceFileAddress) -> bool,
    ask: fn(QueryEngine, SourceFileAddress) -> int,
    said: string,
}

/// A build's last wave: every body a file declares lowered, then its laws found (`file_worked`).
export fn bodies_wave() -> FileWave { FileWave { is_known: file_worked_is_known, ask: file_worked, said: "bodies lowered" } }

/// A check's last wave over the program rooted at `program`: what a check says of each file, found
/// ahead — its laws' errors and warnings, its rule rows, its stale citations (`file_checked`). The
/// asking process reads them all back and says them, so it says what it would alone.
export fn checks_wave(program: string) -> FileWave {
    FileWave {
        is_known: (engine: QueryEngine, file: SourceFileAddress) -> file_checked_is_known(
            engine,
            program,
            file,
        ),
        ask: (engine: QueryEngine, file: SourceFileAddress) -> file_checked(engine, program, file),
        said: "files checked",
    }
}

/// Whether everything a check says of `file` in the program rooted at `program` is kept.
fn file_checked_is_known(engine: QueryEngine, program: string, file: SourceFileAddress) -> bool {
    file_erring_is_known(engine, file) &&
    file_erring(engine, file).errors
}

/// The store at `directory` a program rooted at `package` is made from, and the engine over
/// `definitions` to make it with, worked ahead across `process_count` processes, or by none with
/// fewer than two or where the last build's frontier saw at most `FEW_MOVED` inputs move; with
/// `timed`, each process and each phase says where its time went. The waves parse, run generators
/// and file impls, then ask `last` of every file the program reads.
export fn program_worked(
    directory: string,
    package: string,
    definitions: List<QueryDefinition>,
    process_count: int,
    timed: bool,
    last: FileWave,
) -> Worked {
    let at = AheadAt {
        directory: directory,
        definitions: definitions,
        process_count: process_count,
        timed: timed,
    }
    wave_gathers(GATHERED)
    let alone = ahead(at, (_engine: QueryEngine) -> [], file_words_is_known, file_parsed)
    if process_count < 2 || few_moved(alone.engine) { return alone }
    let _ = alone.store.saved()
    let clock = query_times()
    clock.opened("files parsed", TimedSide.Outside)
    let parsed = files_parsed(at, package)
    clock.closed()
    clock.opened("generators run", TimedSide.Outside)
    let _ = parsed.worked.store.saved()
    let generated = ahead(
        at,
        (_engine: QueryEngine) -> parsed.reached,
        file_generated_is_known,
        generators_run,
    )
    clock.closed()
    clock.opened("impls filed", TimedSide.Outside)
    let filed = impls_filed_for(generated.engine, package)
    let _ = generated.store.saved()
    clock.closed()
    clock.opened(last.said, TimedSide.Outside)
    let lowered = ahead(at, (_engine: QueryEngine) -> parsed.program, last.is_known, last.ask)
    clock.closed()
    if at.timed { eprintln(phases_said(clock, filed)) }
    lowered
}
