import sys
root = sys.argv[1] + "/packages/std-program/src/"

def sub(t, a, b, count=1):
    assert t.count(a) == count, (a[:80], t.count(a))
    return t.replace(a, b)

p = root + "disk_store.av"
t = open(p, encoding="utf-8").read()
t = sub(t, """export fn wave_sharing_begun() -> bool {
    if wave_alone() != null || !wave_table().get().is_empty() { return false }
    let shared? = avra_shared_made(WAVE_SLOTS, WAVE_OCTETS) else { return false }
    wave_table().set([shared])
    true
}""", """export fn wave_sharing_begun(directory: string) -> bool {
    if wave_alone() != null { return false }
    if !wave_table().get().is_empty() {
        if wave_table_of().get() == directory { return false }
        wave_sharing_ended(true)
    }
    let shared? = avra_shared_made(WAVE_SLOTS, WAVE_OCTETS) else { return false }
    wave_table().set([shared])
    wave_table_of().set(directory)
    true
}

/// The store directory the build's table is of: a process that builds another store after it
/// makes that build a table of its own.
once fn wave_table_of() -> Cell<string> { Cell.new("") }""")
t = sub(t, """/// WHAT A BUILD'S PROCESSES LEARN IS SHARED AS THEY LEARN IT, from here until `wave_sharing_ended`:
/// asked before the first wave forks, so every process of every wave maps one table.""",
"""/// WHAT A BUILD'S PROCESSES LEARN IS SHARED AS THEY LEARN IT, from here until `wave_sharing_ended`:
/// asked before each wave forks, the first making the table of the store at `directory`, so every
/// process of every wave of that build maps one table; whether a table was made anew.""")
open(p, "w", encoding="utf-8").write(t)

p = root + "worked_ahead.av"
t = open(p, encoding="utf-8").read()
t = sub(t, """    let sharing = wave_sharing_begun()
""", """    if wave_sharing_begun(store.own.directory) { table_spoiled().set(false) }
""")
t = sub(t, """    if core < 0 {
        wave_sharing_ended(sharing)
        return false
    }""", """    if core < 0 { return false }""")
t = sub(t, """fn within_and_gone<T, R>(
    store: LayeredStore,
    engine: QueryEngine,
    mark: int,
    items: List<T>,""", """fn within_and_gone<T, R>(
    store: LayeredStore,
    engine: QueryEngine,
    items: List<T>,""")
t = sub(t, "        within_and_gone<T, R>(store, engine, mark, items, work, group, core)\n",
           "        within_and_gone<T, R>(store, engine, items, work, group, core)\n")
t = sub(t, """        within_and_gone<T, R>(
            store,
            engine,
            engine.settled_count(),
            items,""", """        within_and_gone<T, R>(
            store,
            engine,
            items,""")
open(p, "w", encoding="utf-8").write(t)
print("ok")

