"""/// ONE ANSWER A PROCESS OF THE BUILD LEARNED, as the table keeps it for the asking process to take:
/// the question, its answer, the questions it read, and whether it is an input.
@derive(Saved)
type SharedEntry = { question: ContentHash, answer: ContentHash, reads: List<int>, input: bool }

fn held_of(e: SharedEntry) -> HeldEntry { HeldEntry { question: e.question, answer: e.answer, reads: e.reads, input: e.input, root: false } }

/// `entry`, settled by this process, kept in the build's table, and an input's kept again apart, so
/// the asking process proves the inputs reading only them.
export fn wave_entry_kept(entry: HeldEntry) {
    let shared? = wave_table().get().first() else { return }
    let bytes = SharedEntry { question: entry.question, answer: entry.answer, reads: entry.reads, input: entry.input }.saved_bytes()
    let _ = avra_shared_kept(shared, WAVE_ENTRIES, entry.question.high_word, entry.question.low_word, bytes, bytes.length)
    if entry.input { let _ = avra_shared_kept(shared, WAVE_INPUTS, entry.question.high_word, entry.question.low_word, bytes, bytes.length) }
}

/// The entry a process of the build kept of `question`, read where it lies.
export fn wave_entry_of(question: ContentHash) -> HeldEntry? {
    let found? = wave_found(WAVE_ENTRIES, question) else { return null }
    let at = found.root_at()
    held_of(SharedEntry.read_from(at.source, at.node))
}

/// Every entry the build's table keeps, or with `inputs` every input's, in question order: the
/// table's own order is the order its processes happened to keep them in.
export fn wave_entries(inputs: bool) -> List<HeldEntry> {
    let shared? = wave_table().get().first() else { return [] }
    let kind = if inputs { WAVE_INPUTS } else { WAVE_ENTRIES }
    let source = SavedSource.Mapped(avra_shared_view(shared))
    let found = [held_of(SharedEntry.read_from(at.source, at.node)) for slot in 0..avra_shared_slots(shared) for from in [avra_shared_slot_start(shared, kind, slot)] if from >= 0 for at in [SavedBytes { source: source, from: from, to: avra_shared_slot_end(shared, kind, slot) }.root_at()]]
    sorted_by_hash(found, (e: HeldEntry) -> e.question)
}

