export fn asked_across<T, R>(
    store: LayeredStore,
    engine: QueryEngine,
    directory: string,
    work: WorkAhead<T, R>,
) -> bool {
    asked_across_while<T, R>(store, engine, directory, work, () -> 0)
}

/// `asked_across`, the asking process doing `meanwhile` once its cores are forked and before it
/// takes anything of theirs: what a witness edits an input in.
export fn asked_across_while<T, R>(
    store: LayeredStore,
    engine: QueryEngine,
    directory: string,
    work: WorkAhead<T, R>,
    meanwhile: fn() -> int,
) -> bool {
    let known_by = work.is_known
    let items = (work.items)(engine)
    if work.process_count < 2 || !at_least(items, WORTH_FORKING, (item) -> !known_by(engine, item)) { return false }
    engine.kept_times()?.opened("the cores", TimedSide.Outside)
    let _ = store.saved()
    let wave = waves_forked().get()
    // LICENSED input.work_ahead: forked workers answer what this process would, never another answer
    let group = if store.has_news() { -1 } else { avra_cores_group(work.process_count) }
    // LICENSED input.work_ahead: forked workers answer what this process would, never another answer
    let core = if group < 0 { -1 } else { avra_cores_fork(group, NO_DESCRIPTOR) }
    if core < 0 {
        engine.kept_times()?.closed()
        return false
    }
    let mark = engine.settled_count()
    if core < work.process_count {
        within_and_gone<T, R>(
            store,
            engine,
            mark,
            items,
            work,
            group,
            core,
            "${learned_dir(directory)}/${wave}-${core}",
        )
    }
    let _ = meanwhile()
    let finished = waited_for(group, work.process_count)
    engine.kept_times()?.closed()
    waves_forked().set(wave + 1)
    if finished < work.process_count { eprintln(cores_unfinished(work.process_count - finished, work.process_count)) }
    store.packs_read_again()
    engine.kept_times()?.opened(ANSWERS_TAKEN, TimedSide.Outside)
    let taken = wave_taken(engine, learned_dir(directory), "${wave}-")
    engine.kept_times()?.closed()
    if work.timed { eprintln("within: ${taken}") }
    true
}

/// ONE PROCESS ANSWERING `work`'s ITEMS BESIDE THE ASKING PROCESS, which does `meanwhile` with
/// the same engine and then takes what the process learned: two stretches of a build that read
/// nothing of each other, done at once. `meanwhile` answers whether the items are still wanted;
/// where they are not, the process is ended and nothing of it is taken. Whether a process was
/// forked, and so `meanwhile` done: where every item is known, or nothing can be forked, neither.
export fn asked_beside<T, R>(
    store: LayeredStore,
    engine: QueryEngine,
    directory: string,
    work: WorkAhead<T, R>,
    meanwhile: fn() -> bool,
) -> bool {
    let known_by = work.is_known
    let items = (work.items)(engine)
    if !items.any((item) -> !known_by(engine, item)) { return false }
    engine.kept_times()?.opened("the cores", TimedSide.Outside)
    let _ = store.saved()
    let wave = waves_forked().get()
    let group = if store.has_news() { -1 } else { avra_cores_group(1) }
    let core = if group < 0 { -1 } else { avra_cores_fork(group, NO_DESCRIPTOR) }
    engine.kept_times()?.closed()
    if core < 0 { return false }
    let learned_at = "${learned_dir(directory)}/${wave}-0"
    if core < 1 {
        within_and_gone<T, R>(
            store,
            engine,
            engine.settled_count(),
            items,
            work with { process_count: 1 },
            group,
            core,
            learned_at,
        )
    }
    if beside_hook() == "killed" { let _ = avra_cores_killed(group, 0) }
    let wanted = meanwhile() && beside_hook() != "unwanted"
    if !wanted { let _ = avra_cores_killed(group, 0) }
    engine.kept_times()?.opened("the cores", TimedSide.Outside)
    let finished = waited_for(group, 1)
    engine.kept_times()?.closed()
    waves_forked().set(wave + 1)
    if !wanted {
        let _ = remove(learned_at)
        if work.timed { eprintln("beside: the process ended, nothing of it taken") }
        return true
    }
    if finished < 1 { eprintln(cores_unfinished(1, 1)) }
    store.packs_read_again()
    engine.kept_times()?.opened(ANSWERS_TAKEN, TimedSide.Outside)
    let taken = wave_taken(engine, learned_dir(directory), "${wave}-")
    engine.kept_times()?.closed()
    if work.timed { eprintln("beside: ${taken}") }
    true
}

/// `AVRA_BESIDE`: a witness's way into a process answering beside the asking one — `killed` ends
/// it before it is waited for, `unwanted` has the asking process want nothing of it.
once fn beside_hook() -> string {
    // LICENSED input.debug_flag: a test hook that ends a process early, so what it owed is witnessed answered without it
    env("AVRA_BESIDE") ?? ""
}

/// A process forked within a build: takes turns at `items` with the engine it was forked holding,
/// publishes what it learned since, and leaves.
fn within_and_gone<T, R>(
    store: LayeredStore,
    engine: QueryEngine,
    mark: int,
    items: List<T>,
    work: WorkAhead<T, R>,
    group: int,
    core: int,
    learned_at: string,
) {
    let known_by = work.is_known
    let ask = work.ask
    mut answered = 0
    mut turn = avra_cores_claimed(group)
    while turn < items.length {
        if !known_by(engine, items[turn]) {
            let _ = ask(engine, items[turn])
            answered = answered + 1
        }
        turn = avra_cores_claimed(group)
    }
    let _ = store.saved_alone()
    written_whole(
        learned_at,
        core_learned(engine.learned_entries_since(mark), engine.stood_answers_since(mark))
            .saved_bytes(),
    )
    if work.timed { eprintln("core ${core}: ${answered} answered within the build") }
    let _ = avra_cores_leave(group, core, answered, 0)
}

/// What the cores of the wave whose files in `dir` begin `prefix` learned, taken by `engine`, each
/// file read once and removed: how many cores were taken, and each refused with why.
fn wave_taken(engine: QueryEngine, dir: string, prefix: string) -> string {
    mut taken = 0
    mut said: List<string> = []
    // LICENSED input.store_io: the store's own files, never an input of what is answered
    for name in list_dir(dir) catch [] {
        if name.contains(".") || !name.starts_with(prefix) { continue }
        // LICENSED input.store_io: the store's own files, never an input of what is answered
        let bytes = match read_bytes("${dir}/${name}") {
            .Ok(b) -> b,
            .Err(_) -> {
                said.push("core ${dir}/${name}: unread, worked out here")
                continue
            },
        }
        let _ = remove("${dir}/${name}")
        let held? = core_held(bytes) else {
            said.push("core ${dir}/${name}: unread, worked out here")
            continue
        }
        let why = core_taken(engine, held)
        if why == null { taken = taken + 1 } else { said.push("core ${dir}/${name} refused: ${why!}") }
    }
    "${taken} cores' answers taken${["; ${s}" for s in said].join("")}"
}

