}

/// A settled aggregate as its boxes, the ROOT last — the address a
/// `StaticAddr` of this name answers.
/// One settled aggregate's layout: every box, child-first, under the static's
/// own name. `home` is the path of the file whose unit first read it, so a
/// per-file module knows which of them it owns. `debug` marks data a program READS but
/// that is no part of what its code DOES — a body's frame, whose label and
/// declaration span move when a line above the body is written — so the code
/// graph resolves a reference to it without hashing it.
@derive(Fingerprint)
@codec
@derive(Saved)
export type Static = { name: string, boxes: List<StaticBox>, home: string? = null, debug: bool = false }

/// Which instructions BRACKET a region — kept beside the enum, like
/// every fact about it, so no consumer re-derives the list.
export fn opens_region(i: Ins) -> bool {
    i is .IfStart || i is .SwitchStart
}

export fn closes_region(i: Ins) -> bool {
    i is .RegionEnd
}

/// Register identity — two registers are one when their indexes
