mkdir -p /work/probes/atk/src && cd /work/probes/atk && printf '[package]\nname = "atk"\nversion = "0.0.1"\n' > avra.toml && cat > src/lib.av <<'EOF'
export type P = { a: int }

export fn make(n: int) -> P { P { a: n } }

export fn callee(x: int) -> int { x + 1 }

export fn shown(x: int) -> int { x }

export fn other(x: int) -> int { x * 2 }
EOF
cat > src/main.av <<'EOF'
use lib.{P, make, callee, shown, other}

fn get(p: P) -> int { p.a }

fn twice(x: int) -> int { callee(x) + callee(x) }

fn said(x: int) -> string { "${shown(x)}" }

fn plain(x: int) -> int { other(x) - 1 }

println("${twice(1)} ${get(make(5))} ${said(7)} ${plain(3)}")
EOF
cp -r src /work/probes/atk-src.orig; ls src

