            let host = hosted_symbol(i)
            if host != null { r.hosted.set(host!, true) }
            let st = static_symbol(i)
            if st != null { r.statics.set(st!, true) }
        }
    }
    for p in ix.static_positions(r.statics.keys()) {
        for sym in static_code_syms(statics[p].boxes) { r.bodies.set(sym, true) }
    }
    r
}

/// A MODULE'S STATICS IN THE ORDER ITS BODIES FIRST READ THEM. A static's name carries
/// ids of the process that named it, so the reads order them, never the name; one no
/// body reads follows, as it stood.
fn in_read_order(statics: List<Static>, bodies: List<Body>, refs: Refs, ix: EmitIndex) -> List<
    Static,
> {
    let read = if refs.whole { refs_of(bodies, statics, ix).statics } else { refs.statics }
    mut by: Map<string, Static> = {}
    for st in statics { by.set(st.name, st) }
    [by.get(n)! for n in read.keys() if by.get(n) != null]
        .concat([st for st in statics if read.get(st.name) == null])
}

/// Does this module carry the name? Every name in a whole-program module;
/// only what its own bodies named in a split one.
fn carries(r: Refs, named: Map<string, bool>, name: string) -> bool { r.whole || named.get(name) != null }

/// The whole program as verified `.ll` text; null means written, a string is
/// the failure.
export fn emit_ll(l: Lowered, path: string, target: string) -> string? {
    let ordered = in_symbol_order(l)
    emit_mode(ordered, emit_index(ordered), path, Owned.Whole, Written.Text, target)
}

/// THE PROGRAM IN EMISSION ORDER: its bodies by symbol name. A module declares and
/// defines in this order, so what it writes is the source's alone, never the order a
/// build met its files in.
export fn in_symbol_order(l: Lowered) -> Lowered {
    l with { fns: sorted_by(l.fns, (a: Body, b: Body) -> text_before(a.name, b.name)) }
}

/// ONE MODULE OF A SPLIT PROGRAM, as bitcode. It declares what its own bodies
/// NAME — LLVM wants a called symbol declared where it is called — and lays out
/// the statics they read: private linkage, so each module's copy is its own.
/// The caller has asked `program_closed`, a whole-program scan with one answer.
export fn emit_closed(l: Lowered, ix: EmitIndex, path: string, which: Owned, target: string) -> string? {
    emit_mode(l, ix, path, which, Written.Bitcode, target)
}

extern fn avra_cores_online() -> int
extern fn avra_disk_free_bytes(path: string) -> int
extern fn avra_file_bytes(path: string) -> int
extern fn avra_file_placed(from: string, to: string) -> int

/// Whether the file `from` now also stands at `to`, linked and renamed onto it, no byte written.
// LICENSED input.staged_output: the build's own output, written and read back by the build
export fn file_placed(from: string, to: string) -> bool { avra_file_placed(from, to) == 0 }

/// The bytes free on the file system holding `path`; absent where it can't be asked.
export fn disk_free_at(path: string) -> int? {
    // LICENSED input.staged_output: the build's own output, written and read back by the build
    let free = avra_disk_free_bytes(path)
    if free < 0 { null } else { free }
}

/// The size of the file at `path`: none where none stands.
// LICENSED input.staged_output: the build's own output, written and read back by the build
export fn file_bytes(path: string) -> int { avra_file_bytes(path) }
extern fn avra_cores_group(count: int) -> int
extern fn avra_cores_fork(group: int, serving: int) -> int
extern fn avra_cores_claimed(group: int) -> int
extern fn avra_cores_leave(group: int, core: int, accepted: int, err: int) -> int
extern fn avra_cores_end_fd(group: int, core: int) -> int
extern fn avra_cores_heard(group: int, core: int) -> int
extern fn avra_cores_finished(group: int) -> int
extern fn avra_fiber_park_fd(fd: int, writable: int, timeout_ms: int) -> int

/// How long a wait for a forked emit lasts before it looks again.
const EMIT_WAIT_MS: int = 1000

/// How many processes the machine runs at once.
export fn emit_cores() -> int {
    // LICENSED input.machine_width: the core count sets how many processes make objects, never what they hold
    avra_cores_online()
}

/// `count` turns taken across `processes` forked processes, each taking the next turn no other
/// has taken until none is left, so none sits idle while another still holds turns: whether
/// every process ran each turn it took clean; absent where none forked.
export fn turns_across(processes: int, count: int, run: fn(int) -> bool) -> bool? {
    // LICENSED input.work_ahead: forked workers answer what this process would, never another answer
    let group = avra_cores_group(processes)
    if group < 0 { return null }
    // LICENSED input.work_ahead: forked workers answer what this process would, never another answer
    let core = avra_cores_fork(group, 0 - 1)
    if core < 0 { return null }
    if core < processes {
        mut clean = true
        mut turn = avra_cores_claimed(group)
        while turn < count {
            if !run(turn) { clean = false }
            turn = avra_cores_claimed(group)
        }
        let _ = avra_cores_leave(group, core, 0, if clean { 0 } else { 1 })
    }
    for c in 0..processes {
        while avra_cores_heard(group, c) != 0 { let _ = avra_fiber_park_fd(avra_cores_end_fd(group, c), 0, EMIT_WAIT_MS) }
    }
    avra_cores_finished(group) == processes
}

/// How many objects are made at once: a worker is a thread of this process and holds one
/// module, so the width is the machine's cores, at most sixteen.
export fn emit_width() -> int {
    // LICENSED input.machine_width: the core count sets how many objects are made at once, never what they hold
    let cores = avra_cores_online()
    when {
        cores < 1 -> 1
        cores > 16 -> 16
        _ -> cores
    }
}

/// The same module as an OBJECT, optimized and generated in this process at
/// clang's level — BY A WORKER: the module is built here and handed over, and
/// `objects_made` waits for every one handed. At most `workers` work at once; none
/// named is `emit_width`.
export fn emit_object(
    l: Lowered,
    ix: EmitIndex,
    path: string,
    which: Owned,
    opt: int,
    target: string,
    workers: int = 0,
) -> string? {
    emit_mode(
        l,
        ix,
        path,
        which,
        Written.Object(opt, if workers < 1 { emit_width() } else { workers }),
        target,
    )
}

/// The link option that drops code nothing reaches: Mach-O drops by
/// atom, ELF by section — and every definition is emitted in one of its own.
export fn unreached_dropped() -> string {
    if avra_llvm_drops_by_atom() != 0 { "-Wl,-dead_strip" } else { "-Wl,--gc-sections" }
}

/// The link's words that name the binary where it lands, not where it is
/// staged: Mach-O's build id hashes the output's name, so one set of objects
/// staged under two names links two different binaries.
export fn link_named(binary: string) -> List<string> {
    if links_with_ld64() { ["-Wl,-final_output,${binary}"] } else { [] }
}

/// Whether the host links with ld64: the Mach-O host is the one that drops
/// by atom.
export fn links_with_ld64() -> bool { avra_llvm_drops_by_atom() != 0 }

/// The link's words that keep each host fn's symbol whatever reaches it:
/// an undefined reference the link must resolve, spelled as the object
/// format spells a C name.
export fn host_kept_words(names: List<string>) -> List<string> {
    let lead = if avra_llvm_drops_by_atom() != 0 { "_" } else { "" }
    ["-Wl,-u,${lead}${n}" for n in names]
}

/// Every object handed to a worker, written — null — or the refusal.
export fn objects_made() -> string? {
    let unwritten = avra_llvm_objects_unwritten()
    if unwritten == 0 { null } else { "avra: ${unwritten} object(s) could not be written" }
}

/// Whether the objects this process writes carry the runtime's hot leaves
/// inlined (`AVRA_INLINE_RUNTIME=0` keeps them calls).
export fn inlines_runtime() -> bool { avra_llvm_inlines_runtime() != 0 }

/// The ways the objects this process writes are emitted that its environment chooses — frame
/// pointers kept, boxes counted by type, stores tracked — as one word: each makes another object of
/// the same code, so a kept object's key holds it.
export fn emit_modes() -> int { avra_llvm_emit_modes() }

/// What a module is written as. An `Object`'s module leaves with its context,
/// for a worker to write and dispose.
enum Written { Text, Bitcode, Object(opt: int, workers: int) }

